<?php
session_start();if(!isset($_SESSION['id'],$_SESSION['role'])||!in_array($_SESSION['role'],['student','faculty'],true)){header('Location:dashboard.php');exit;}include 'db.php';$bid=(int)($_GET['id']??0);$uid=(int)$_SESSION['id'];if($bid<1){header('Location:my_books.php');exit;}
$s=$conn->prepare("SELECT book_id FROM borrowings WHERE id=? AND member_id=? AND status='issued' LIMIT 1");$s->bind_param('ii',$bid,$uid);$s->execute();$loan=$s->get_result()->fetch_assoc();$s->close();if(!$loan){header('Location:my_books.php?error=invalid');exit;}
$conn->begin_transaction();try{$s=$conn->prepare("UPDATE borrowings SET status='returned',returned_at=NOW() WHERE id=? AND member_id=? AND status='issued'");$s->bind_param('ii',$bid,$uid);$s->execute();if($s->affected_rows!==1)throw new Exception();$s->close();$s=$conn->prepare('UPDATE books SET quantity=quantity+1 WHERE id=?');$s->bind_param('i',$loan['book_id']);$s->execute();$s->close();$conn->commit();header('Location:my_books.php?success=returned');}catch(Exception $e){$conn->rollback();header('Location:my_books.php?error=failed');}exit;
